sap.ui.define([
    "sap/m/MessageToast"
], function (MessageToast) {
    "use strict";

    async function onDownloadPDFSalidaMinisterio(oController, sButtonId) {
        try {
            await oController._ensurePdfToolkit();
            await oController._ensureMDFData();
            
            const PDFLibRef = window.PDFLib || oController._pdfLibRef;
            const html2canvasRef = window.html2canvas || oController._html2canvasRef;

            if (!PDFLibRef || !html2canvasRef) {
                throw new Error("No se pudieron cargar las bibliotecas PDF/Canvas requeridas.");
            }

            const aUsers = oController.getSelectedUsers();
            console.log(oController.getSelectedUsers());
            
            if (aUsers.length === 0) {
                MessageToast.show("Seleccione al menos un colaborador.");
                return;
            }

            const sFechaDGT3 = oController.sFechaDGT3
                ? new Date(new Date(oController.sFechaDGT3).setDate(new Date(oController.sFechaDGT3).getDate() + 1))
                    .toLocaleDateString('es-ES', { day: '2-digit', month: 'long', year: 'numeric' })
                : "No disponible";
                
            const sFechaHoy = new Date().toLocaleDateString('es-ES', {
                day: 'numeric',
                month: 'long',
                year: 'numeric'
            }).replace(' de ', ' de ').replace(',', ' del');

            let sTableRows = "";
            for (let user of aUsers) {
                const causa = oController.getEventReasonDescription(user.eventReason);
                console.log(user.eventReason);
                
                const sal = Number(user.paycompvalue).toLocaleString('en-US', {
                    minimumFractionDigits: 2,
                    maximumFractionDigits: 2
                });
                
                sTableRows += `<tr>
                    <td style="border: solid #000000 0.5pt;"><p><span style="font-size:10pt;font-family:Arial,sans-serif;">${user.firstName} ${user.lastName} ${user.secondLastName || ''}</span></p></td>
                    <td style="border: solid #000000 0.5pt;text-align: center;"><p><span style="font-size:10pt;font-family:Arial,sans-serif;">${user.nationalId}</span></p></td>
                    <td style="border: solid #000000 0.5pt;text-align: center;"><p><span style="font-size:10pt;font-family:Arial,sans-serif;">${oController.formatFechaCorta(user.endDate) || "COMPLETAR"}</span></p></td>
                    <td style="border: solid #000000 0.5pt;text-align: center;"><p><span style="font-size:10pt;font-family:Arial,sans-serif;">RD$ ${sal}</span></p></td>
                    <td style="border: solid #000000 0.5pt;text-align: center;"><p><span style="font-size:10pt;font-family:Arial,sans-serif;">${causa}</span></p></td>
                </tr>`;
            }

            let htmlRaw = `<p><span style="font-size:11pt;font-family:Arial,sans-serif;">Santo Domingo, R. D.</span></p>
                <p><span style="font-size:11pt;font-family:Arial,sans-serif;">${sFechaHoy}.</span></p>
                <p><br></p>
                <p style="font-size:11pt;font-family:Arial,sans-serif; margin:0;">Señores:</p>
                <p style="font-size:11pt;font-family:Arial,sans-serif; font-weight:bold; margin:0;">MINISTERIO DE TRABAJO</p>
                <p style="font-size:11pt;font-family:Arial,sans-serif; margin:0;">Ciudad.-</p>
                <p style="font-size:12pt;font-family:Arial,sans-serif; margin:0;"> </p>
                <p style="text-align: justify;"><span style="font-size:11pt;font-family:Arial,sans-serif;">Distinguidos Señores:</span></p>
                <p style="font-size:12pt;font-family:Arial,sans-serif; margin:0;"> </p>
                <p style="text-align: justify;"><span style="font-size:11pt;font-family:Arial,sans-serif;">Por medio de la presente y de conformidad con el Artículo 75, de nuestro Código de Trabajo, le estamos comunicando la salida de:</span></p>
                <div align="left">
                    <table style="border: none; border-collapse: collapse; width: 100%;">
                        <tbody>
                            <tr>
                                <td style="color:#002060;background-color:#002060;border: solid #000000 0.5pt;">
                                    <p style="text-align: center;"><span style="color:#ffffff;font-size:10pt;font-family:Arial,sans-serif;">Colaborador</span></p>
                                </td>
                                <td style="color:#002060;background-color:#002060;border: solid #000000 0.5pt;">
                                    <p style="text-align: center;"><span style="color:#ffffff;font-size:10pt;font-family:Arial,sans-serif;">Cédula</span></p>
                                </td>
                                <td style="color:#002060;background-color:#002060;border: solid #000000 0.5pt;">
                                    <p style="text-align: center;"><span style="color:#ffffff;font-size:10pt;font-family:Arial,sans-serif;">Fecha salida</span></p>
                                </td>
                                <td style="color:#002060;background-color:#002060;border: solid #000000 0.5pt;">
                                    <p style="text-align: center;"><span style="color:#ffffff;font-size:10pt;font-family:Arial,sans-serif;">Salario</span></p>
                                </td>
                                <td style="color:#002060;background-color:#002060;border: solid #000000 0.5pt;">
                                    <p style="text-align: center;"><span style="color:#ffffff;font-size:10pt;font-family:Arial,sans-serif;">Causa</span></p>
                                </td>
                            </tr>
                            ${sTableRows}
                        </tbody>
                    </table>
                </div>
                <p><span style="font-size:11pt;font-family:Arial,sans-serif;">Hacemos esto para los fines de lugar.&nbsp;</span></p>
                <p><span style="font-size:11pt;font-family:Arial,sans-serif;">Atentamente,</span></p>`;

            // Definir firmas
            const firmaHTML = `
                <p><br></p>
                <p><br></p>
                <p style="font-size:11pt;font-family:Arial,sans-serif; font-weight:bold; margin:0;">Glenys Reyes&nbsp;</p>
                <p style="font-size:11pt;font-family:Arial,sans-serif; font-weight:bold; margin:0;">Gerente de Gestión de Personas.</p>
                <p style="font-size:11pt;font-family:Arial,sans-serif; margin:0;">
                    <strong>RNL: </strong>101004843-0002
                </p>
                <p><strong><span style="font-size:11pt;font-family:Arial,sans-serif;">Anexo: </span></strong><span style="font-size:11pt;font-family:Arial,sans-serif;">Carta firmada del colaborador</span></p>
                <p><span style="font-size:11pt;font-family:Arial,sans-serif;">El DGT-3 fue presentado en fecha ${sFechaDGT3}</span></p>`;

            const firmaComun = `
                <p style="margin: auto 0px;padding: 0px;font-weight: normal;font-style: normal;vertical-align: baseline;background-color: transparent;color: windowtext;text-align: left;text-indent: 0px;"><img src="data:image/png;base64," style="width: 162px; height: 106.272px;"></p>
                <p style="font-size:11pt;font-family:Arial,sans-serif; font-weight:bold; margin:0;">Glenys Reyes&nbsp;</p>
                <p style="font-size:11pt;font-family:Arial,sans-serif; font-weight:bold; margin:0;">Gerente de Gestión de Personas.</p>
                <p style="font-size:11pt;font-family:Arial,sans-serif; margin:0;">
                    <strong>RNL: </strong>101004843-0002
                </p>
                <p><strong><span style="font-size:11pt;font-family:Arial,sans-serif;">Anexo: </span></strong><span style="font-size:11pt;font-family:Arial,sans-serif;">Carta firmada del colaborador</span></p>
                <p><span style="font-size:11pt;font-family:Arial,sans-serif;">El DGT-3 fue presentado en fecha ${sFechaDGT3}</span></p>`;

            if (sButtonId === "container-gestordoc---View1--wordDataInfo") {
                htmlRaw += firmaHTML;
                const header = `
                    <html xmlns:o='urn:schemas-microsoft-com:office:office'
                          xmlns:w='urn:schemas-microsoft-com:office:word'
                          xmlns='http://www.w3.org/TR/REC-html40'>
                    <head><meta charset='utf-8'><title>Documento Word</title></head><body>`;
                const footer = "</body></html>";
                const fullHTML = header + htmlRaw + footer;

                const blob = new Blob(['\ufeff', fullHTML], {
                    type: "application/msword"
                });

                const fileName = `Salida_Ministerio.doc`;
                const link = document.createElement("a");
                link.href = URL.createObjectURL(blob);
                link.download = fileName;
                document.body.appendChild(link);
                link.click();

                document.body.removeChild(link);
                URL.revokeObjectURL(link.href);

            } else {
                htmlRaw += firmaComun;
                const contentBlocks = htmlRaw.split("<!--PAGEBREAK-->");
                const existingPdfBytes = await fetch("pdf/hojaMetaldom.pdf").then(res => res.arrayBuffer());
                const pdfDoc = await PDFLibRef.PDFDocument.load(existingPdfBytes);
                const [templatePage] = pdfDoc.getPages();
                const { width, height } = templatePage.getSize();
                const templatePageImage = await pdfDoc.embedPage(templatePage);

                for (const blockHtml of contentBlocks) {
                    const div = document.createElement("div");
                    div.style.width = "794px";
                    div.style.height = "730px";
                    div.style.padding = "40px";
                    div.style.backgroundColor = "white";
                    div.style.fontSize = "12px";
                    div.style.boxSizing = "border-box";
                    div.style.position = "absolute";
                    div.style.top = "-9999px";
                    div.innerHTML = blockHtml;
                    document.body.appendChild(div);

                    const canvas = await html2canvasRef(div, {
                        scale: 2,
                        useCORS: true
                    });
                    const imgData = canvas.toDataURL("image/png");

                    document.body.removeChild(div);

                    const img = await pdfDoc.embedPng(imgData);
                    const newPage = pdfDoc.addPage([width, height]);
                    newPage.drawPage(templatePageImage);

                    const imgWidth = width * 0.9;
                    const imgHeight = (img.height * imgWidth) / img.width;

                    newPage.drawImage(img, {
                        x: (width - imgWidth) / 2,
                        y: height - imgHeight - 170,
                        width: imgWidth,
                        height: imgHeight,
                    });
                }

                pdfDoc.removePage(0);

                const pdfBytes = await pdfDoc.save();
                const fileName = `Salida_Ministerio.pdf`;

                const blob = new Blob([pdfBytes], { type: "application/pdf" });
                const link = document.createElement("a");
                link.href = URL.createObjectURL(blob);
                link.download = fileName;
                link.click();

                URL.revokeObjectURL(link.href);
            }

            const mensaje = aUsers.length > 1
                ? `${aUsers.length} documentos generados correctamente.`
                : "Documento generado correctamente.";
            MessageToast.show(mensaje);

        } catch (error) {
            console.error("Error generando el documento:", error);
            MessageToast.show("Error generando el documento: " + error.message);
        }
    }

    return {
        onDownloadPDFSalidaMinisterio
    };
});